changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS std_code_value_item_id_seq;
ALTER SEQUENCE std_code_value_item_id_seq OWNED BY std_code_value.item_id;
SELECT setval(
    'std_code_value_item_id_seq',
    GREATEST(COALESCE((SELECT MAX(item_id) FROM std_code_value), 0), 1),
    COALESCE((SELECT MAX(item_id) FROM std_code_value), 0) > 0
);
ALTER TABLE std_code_value ALTER COLUMN item_id SET DEFAULT nextval('std_code_value_item_id_seq'::regclass);

CREATE SEQUENCE IF NOT EXISTS std_code_mapping_map_id_seq;
ALTER SEQUENCE std_code_mapping_map_id_seq OWNED BY std_code_mapping.map_id;
SELECT setval(
    'std_code_mapping_map_id_seq',
    GREATEST(COALESCE((SELECT MAX(map_id) FROM std_code_mapping), 0), 1),
    COALESCE((SELECT MAX(map_id) FROM std_code_mapping), 0) > 0
);
ALTER TABLE std_code_mapping ALTER COLUMN map_id SET DEFAULT nextval('std_code_mapping_map_id_seq'::regclass);
